import Foundation

/// A fully-resolved, typed command ready for execution — the Reflex mirror of
/// `brain.Plan` in Jev Voice. Every value is either a closed-set choice from
/// the Laya router, a rule target, or a candidate cut verbatim from the
/// transcript by `PayloadExtractor`. Nothing here is generated by a model.
public struct CommandPlan: Sendable, Equatable {
    /// Which action kind should run ("open_app", "web_search", "shortcut", ...).
    public let action: String
    /// Whole-plan confidence: the minimum over the judgements/extractions the
    /// plan relied on. Below `DecisionArbiter.minConfidence` the dispatcher
    /// no-ops instead of guessing.
    public let confidence: Double
    /// Trailing "and press enter / hit submit" → press return after typing.
    public let submit: Bool
    /// The payload should land in a specific named app ("type hello in notes").
    public let inApp: Bool
    /// This plan is one segment of a compound utterance (executed in order).
    public let compound: Bool
    /// Continuous confidence in [0,1] that the user was actually addressing
    /// Reflex (results of the "addressed" gate in always-on/vocal mode).
    public let addressed: Double
    /// Typed action arguments (site, folder, direction, amount, percent, ...).
    public let args: [String: String]
    /// The verbatim payload candidates cut out of the transcript.
    public let candidates: Candidates
    /// The origin transcript this plan was built from.
    public let transcript: String

    public init(
        action: String,
        confidence: Double,
        candidates: Candidates,
        transcript: String,
        submit: Bool = false,
        inApp: Bool = false,
        compound: Bool = false,
        addressed: Double = 1.0,
        args: [String: String] = [:]
    ) {
        self.action = action
        self.confidence = confidence
        self.candidates = candidates
        self.transcript = transcript
        self.submit = submit
        self.inApp = inApp
        self.compound = compound
        self.addressed = addressed
        self.args = args
    }

    /// Builds the full plan for a routed transcript: extract candidates, pile
    /// rank-1 confidence from the Noul/Rule, and let the arbiter's gate decide
    /// whether it acts at all.
    public static func make(
        target: String,
        confidence: Double,
        transcript: String
    ) -> CommandPlan {
        let candidates = PayloadExtractor.extract(from: transcript, target: target)
        return CommandPlan(
            action: target,
            confidence: confidence,
            candidates: candidates,
            transcript: transcript,
            submit: candidates.submit,
            inApp: candidates.inApp != nil,
            addressed: confidence,
            args: Self.planArgs(for: target, candidates: candidates)
        )
    }

    /// Reduces the rich candidates into the flat arg table the dispatcher and
    /// the CLI both consume.
    private static func planArgs(for action: String, candidates: Candidates) -> [String: String] {
        var args: [String: String] = [:]
        if let app = candidates.appName { args["appName"] = app }
        if let query = candidates.query { args["query"] = query }
        if let site = candidates.site { args["site"] = site }
        if let text = candidates.text { args["text"] = text }
        if let title = candidates.title { args["title"] = title }
        if let folder = candidates.folder { args["folder"] = folder }
        if let direction = candidates.direction { args["direction"] = direction }
        if let amount = candidates.amount { args["amount"] = amount }
        if let shortcut = candidates.shortcutName { args["shortcutName"] = shortcut }
        if let app = candidates.inApp { args["inApp"] = app }
        if let index = candidates.linkIndex { args["linkIndex"] = String(index) }
        switch candidates.volumeOp {
        case .percent(let p): args["volumePercent"] = String(p)
        case .up: args["volumeDelta"] = "+"
        case .down: args["volumeDelta"] = "-"
        case .mute: args["volumeOp"] = "mute"
        case .unmute: args["volumeOp"] = "unmute"
        case .max: args["volumeOp"] = "max"
        case .half: args["volumeOp"] = "half"
        case nil: break
        }
        return args
    }
}
